function comboVisualCardMarkup(entry, context) {
  const item=typeof entry==='string'?{card:entry}:(entry||{});
  const name=item.card||'', displayName=item.label||name||'Card', specific=Boolean(name), frame=item.frame||'any';
  const rawLevel=item.level??'', rawScale=item.scale??'';
  const level=rawLevel!==''?(/^(level|rank|link)\b/i.test(String(rawLevel))?String(rawLevel):'Level '+rawLevel):'';
  const scale=rawScale!==''?'Scale '+rawScale:'';
  const attributes=[...new Set((displayName+' '+(item.type||'')).match(/\b(?:DARK|LIGHT|EARTH|WIND|FIRE|WATER|DIVINE)\b/gi)?.map(x=>x.toUpperCase())||[])];
  const attribute=item.attribute||(attributes.length===1?attributes[0]:'');
  const qty=Number(item.qty)>1?'<span class="deck-card-qty">×'+Number(item.qty)+'</span>':'';
  const isDiscardCard=!specific&&frame==='any'&&rawLevel===''&&rawScale===''&&!attribute&&/^(card to discard|discard card|discard sent to gy|other cards in hand|drawn card|card drawn|any card)$/i.test(displayName);
  const common=' class="deck-card-image-wrap combo-visual-card-frame';
  const frameOpen=specific||isDiscardCard?'<span'+common+(isDiscardCard?' combo-discard-frame':'')+'">':'<span'+common+' combo-generic-frame" data-generic-frame="'+escapeCardText(frame)+'">';
  const art=specific
    ? '<img class="deck-card-image" data-card-name="'+escapeCardText(name)+'" alt="'+escapeCardText(name)+' card image" loading="lazy"><span class="deck-card-image-fallback" aria-hidden="true">'+escapeCardText(name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join(''))+'</span>'
    : isDiscardCard?'<img class="combo-card-back-art" src="card-back.svg" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span>'
    : '<span class="combo-generic-face" aria-hidden="true"><span class="combo-generic-face-top">'+escapeCardText(attribute||'Requirement')+'</span><span class="combo-generic-face-level">'+escapeCardText([level,scale].filter(Boolean).join(' · '))+'</span><span class="combo-generic-face-art">'+escapeCardText(item.displayRequirement||item.nameRequirement||displayName)+'</span><span class="combo-generic-face-type">'+escapeCardText(item.type||'Any card')+'</span></span>';
  const button=specific
    ? '<button type="button" class="combo-visual-card '+context+'" data-card-name="'+escapeCardText(name)+'" aria-label="View card details for '+escapeCardText(name)+'" aria-haspopup="dialog" aria-controls="card-detail-overlay">'
    : '<button type="button" class="combo-visual-card combo-generic-card '+context+'" data-generic-preview data-generic-label="'+escapeCardText(displayName)+'" data-generic-type="'+escapeCardText(item.type||'Any card')+'" data-generic-frame="'+escapeCardText(frame)+'" data-generic-level="'+escapeCardText(level)+'" data-generic-scale="'+escapeCardText(String(rawScale))+'" data-generic-attribute="'+escapeCardText(attribute)+'" data-generic-requirements="'+escapeCardText(item.requirements||'This placeholder represents a card with no specific name or artwork.')+'" aria-label="View type and requirements for '+escapeCardText(displayName)+'" aria-haspopup="dialog" aria-controls="card-detail-overlay">';
  return button+frameOpen+art+qty+'</span><span class="combo-visual-card-name">'+escapeCardText(displayName)+'</span>'+(!specific&&!isDiscardCard&&item.type&&item.type!=='Any card'?'<span class="combo-generic-requirement">'+escapeCardText(item.type)+'</span>':'')+'</button>';
}
function comboStartingHandMarkup(entries) {
  return (entries||[]).flatMap(entry=>{
    const item=typeof entry==='string'?{card:entry}:(entry||{});
    const count=Math.max(1,Math.min(10,Number(item.qty)||1));
    return Array.from({length:count},()=>Object.assign({},item,{qty:1}));
  }).map(item=>comboVisualCardMarkup(item,'combo-hand-card')).join('');
}
function pileCount(entries) { return (entries||[]).reduce((sum,entry)=>sum+Math.max(1,Number(entry&&entry.qty)||1),0); }
function pileIconMarkup(kind, entries, topEntry) {
  const back='card-back.svg';
  if(kind==='main'||(kind==='extra'&&!topEntry))return '<img class="combo-pile-top-image" src="'+back+'" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span>';
  if(topEntry&&topEntry.card)return '<img class="combo-pile-top-image deck-card-image" data-card-name="'+escapeCardText(topEntry.card)+'" alt="Most recent card: '+escapeCardText(topEntry.card)+'" loading="lazy"><span class="deck-card-image-fallback" aria-hidden="true">'+escapeCardText(topEntry.card.split(/\s+/).slice(0,2).map(x=>x[0]||'').join(''))+'</span>';
  if(topEntry)return '<span class="combo-pile-top-generic combo-generic-frame" data-generic-frame="'+escapeCardText(topEntry.frame||'any')+'"><span class="combo-generic-art"></span>'+(topEntry.scale||topEntry.level?'<span class="combo-generic-meta">'+escapeCardText(topEntry.scale||topEntry.level)+'</span>':'')+'</span>';
  return '<span class="combo-zone-empty">Empty</span>';
}
function comboPileZoneMarkup(zone, value) {
  let entries=[],count=0,topEntry=null,note='';
  const kind=zone.key;
  if(value===undefined)return '<div class="combo-field-zone combo-pile-zone"><span class="combo-zone-label">'+zone.label+'</span><span class="combo-zone-empty">Not tracked</span></div>';
  if(kind==='main'||kind==='extra'){
    entries=value&&value.entries||[];count=value&&value.count||0;topEntry=value&&value.topEntry||null;note=value&&value.note||'';
  } else {
    entries=Array.isArray(value)?value:[];count=pileCount(entries);topEntry=entries.length?entries[entries.length-1]:null;
    note=entries.length?'The last card shown is the most recently added card. Select any card to open its details.':'No cards are currently tracked in this pile.';
  }
  const names=entries.map(entry=>entry.card||entry.label||'Card').join(', ');
  const icon=pileIconMarkup(kind,entries,topEntry);
  const body=count?'<button type="button" class="combo-pile-trigger" data-pile-kind="'+kind+'" data-pile-count="'+count+'" data-pile-note="'+escapeCardText(note)+'" data-pile-entries="'+escapeCardText(JSON.stringify(entries))+'" aria-label="Open '+zone.label+' card list, '+count+' cards"><span class="combo-pile-top">'+icon+'</span><b>'+count+' '+(count===1?'card':'cards')+'</b><span>View cards</span></button>':'<span class="combo-zone-empty">Empty</span>';
  return '<div class="combo-field-zone combo-pile-zone'+(count?' occupied':'')+'" aria-label="'+zone.label+(count?': '+escapeCardText(names):': empty')+'"><span class="combo-zone-label">'+zone.label+'</span>'+body+'</div>';
}
function comboFieldBoardMarkup(field, heading, note, handEntries) {
  const rows=[
    [{key:null,label:'',empty:true},{key:null,label:'',empty:true},{key:'emzLeft',label:'Extra Monster Zone'},{key:null,label:'',empty:true},{key:'emzRight',label:'Extra Monster Zone'},{key:null,label:'',empty:true},{key:'banished',label:'Banished'}],
    [{key:'field',label:'Field Zone'},{key:'monster1',label:'Monster Zone'},{key:'monster2',label:'Monster Zone'},{key:'monster3',label:'Monster Zone'},{key:'monster4',label:'Monster Zone'},{key:'monster5',label:'Monster Zone'},{key:'grave',label:'Graveyard'}],
    [{key:'extra',label:'Extra Deck'},{key:'spell1',label:'Spell / Trap Zone'},{key:'spell2',label:'Spell / Trap Zone'},{key:'spell3',label:'Spell / Trap Zone'},{key:'spell4',label:'Spell / Trap Zone'},{key:'spell5',label:'Spell / Trap Zone'},{key:'main',label:'Main Deck'}]
  ];
  const html=rows.map(row=>row.map(zone=>{
    if(zone.empty)return '<div class="combo-field-zone combo-field-empty-space" aria-hidden="true"></div>';
    const value=field&&field[zone.key];
    if(['grave','banished','main','extra'].includes(zone.key))return comboPileZoneMarkup(zone,value);
    const item=typeof value==='string'?{card:value}:value;
    const occupied=item&&(item.card||item.label),displayName=occupied?(item.label||item.card):'';
    const body=occupied?comboVisualCardMarkup(item,'combo-zone-card')+
      (item.materials&&item.materials.length?'<span class="combo-material-note">'+item.materials.map(x=>(x.qty||1)+' '+escapeCardText(x.card||x.label||x)).join(', ')+'</span>':'')+(item.note?'<span class="combo-material-note">'+escapeCardText(item.note)+'</span>':''):
      '<span class="combo-zone-empty">Empty</span>';
    return '<div class="combo-field-zone'+(occupied?' occupied':'')+'" aria-label="'+zone.label+(occupied?': '+escapeCardText(displayName):': empty')+'"><span class="combo-zone-label">'+zone.label+'</span>'+body+'</div>';
  }).join('')).join('');
  const handMarkup=Array.isArray(handEntries)?'<section class="combo-field-hand" aria-label="Hand after '+escapeCardText(heading)+'"><div class="combo-field-hand-heading"><b>Hand</b><span>'+pileCount(handEntries)+' '+(pileCount(handEntries)===1?'card':'cards')+'</span></div><div class="combo-field-hand-cards">'+(handEntries.length?comboStartingHandMarkup(handEntries):'<span class="combo-hand-empty">No tracked cards in hand</span>')+'</div></section>':'';
  return '<section class="combo-visual-panel combo-field-panel"><div class="combo-visual-panel-heading"><h3>'+heading+'</h3>'+(note?'<p>'+escapeCardText(note)+'</p>':'')+'</div><div class="combo-field-grid" role="group" aria-label="'+heading+' board state">'+html+'</div>'+handMarkup+'</section>';
}
function comboTextOnlyMarkup(combo, stepIndex, visual) {
  const handVisual = visual?.hand || [];
  const describeField = field => Object.values(field || {}).map(card=>card?.card || card?.label || (typeof card==='string'?card:'')).filter(Boolean).join(', ');
  const playerField = visual ? (describeField(visual.fieldBefore) || 'Empty') : '';
  const opponentField = describeField(visual?.opponentBefore);
  const discardCount=(handVisual||[]).filter(item=>item&&!item.card&&/discard/i.test((item.label||'')+' '+(item.requirements||''))).reduce((sum,item)=>sum+Math.max(1,Number(item.qty)||1),0);
  const backArt=discardCount?'<div class="combo-mobile-cardbacks" role="img" aria-label="Card-back placeholders for generic discard cards">'+Array.from({length:discardCount},()=>'<span class="combo-mobile-cardback"><img class="combo-card-back-art" src="card-back.svg" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span></span>').join('')+'</div>':'';
  const setup = '<div class="opening-hand"><b>Starting hand</b><span>'+escapeCardText(combo.hand)+'</span>'+backArt+'</div>'+
    (playerField?'<div class="line-condition"><b>Your field</b><span>'+escapeCardText(playerField)+'</span></div>':'')+
    (opponentField?'<div class="line-condition"><b>Opponent’s field</b><span>'+escapeCardText(opponentField)+'</span></div>':'')+
    '<div class="line-condition"><b>Before you start</b><span>'+escapeCardText(combo.condition)+'</span></div>';
  const step = stepIndex === 0 ? '<div>'+setup+'</div>' : '<p>'+escapeCardText(combo.steps[stepIndex-1])+'</p>';
  return '<div class="combo-text-only"><article class="line-step current"><span>STEP '+stepIndex+'</span>'+step+'</article>'+
    comboResultAndControls(combo,stepIndex)+'</div>';
}

function comboResultAndControls(combo, stepIndex) {
  return '<div class="line-result"><b>Line result</b><span>'+escapeCardText(combo.result)+'</span></div><div class="combo-actions">'+
    '<button type="button" class="line-prev" '+(stepIndex===0?'disabled':'')+'>← Previous</button><span class="step-count">STEP '+stepIndex+' OF '+combo.steps.length+'</span>'+
    '<button type="button" class="line-next next">'+(stepIndex===combo.steps.length?'Restart line ↺':'Next step →')+'</button></div>';

}
function comboBoardZones(field, state, deckListsForDeck, baseHandNames) {
  const source=deckListsForDeck||{main:[],extra:[]};
  const removeCounts=list=>{const counts=new Map();(list||[]).forEach(entry=>{const name=typeof entry==='string'?entry:entry.card;if(name)counts.set(name,(counts.get(name)||0)+Math.max(1,Number(entry.qty)||1))});return counts};
  const mainRemoved=removeCounts([...(baseHandNames||[]),...((state&&state.mainRemoved)||[])]);
  (state?.mainReturned||[]).forEach(entry=>{const name=typeof entry==='string'?entry:entry.card;if(name)mainRemoved.set(name,Math.max(0,(mainRemoved.get(name)||0)-(Number(entry.qty)||1)))});
  const mainEntries=[];
  (source.main||[]).forEach(([name,qty])=>{const left=Math.max(0,qty-(mainRemoved.get(name)||0));if(left)mainEntries.push({card:name,qty:left})});
  const extraRemoved=removeCounts((state&&state.extraRemoved)||[]),extraEntries=[];
  (source.extra||[]).forEach(([name,qty])=>{const left=Math.max(0,qty-(extraRemoved.get(name)||0));if(left)extraEntries.push({card:name,qty:left})});
  const faceUp=(state&&state.extraFaceUp)||[];
  const mainTotal=Math.max(0,pileCount(mainEntries)-(Number(state&&state.mainUnknownRemoved)||0));
  const mainUnknown=Number(state&&state.mainUnknownRemoved)||0;
  const mainNote=mainUnknown?'The fixed list is shown minus named cards; '+mainUnknown+' unidentified card'+(mainUnknown===1?' is':'s are')+' also out of the Main Deck, so its exact identity is not known.':'The list shows cards remaining after the named cards tracked in this combo.';
  const extraUnknown=Number(state&&state.extraUnknownRemoved)||0;
  const extraTotal=Math.max(0,pileCount(extraEntries)+pileCount(faceUp)-extraUnknown);
  const extraNote=(faceUp.length?'Face-up Pendulum cards are listed last; the most recent Pendulum card appears as the pile icon.':'The most recent card is not knowable while the Extra Deck is face-down, so its icon uses the card back.')+(extraUnknown?' '+extraUnknown+' unidentified Extra Deck card'+(extraUnknown===1?' is':'s are')+' also out of the Deck.':'');
  return Object.assign({},field||{}, {
    grave:state&&state.grave||[],banished:state&&state.banished||[],
    main:{entries:mainEntries,count:mainTotal,note:mainNote},
    extra:{entries:extraEntries.concat(faceUp),count:extraTotal,topEntry:faceUp.length?faceUp[faceUp.length-1]:null,note:extraNote}
  });
}
function comboVisualMarkup(combo, visual, stepIndex) {
  const steps = ['Starting hand & fields', ...visual.steps.map((item,i)=>item.flow?.action || 'Step '+(i+1))];
  const nav = '<nav class="combo-visual-step-nav" aria-label="Choose a combo step">'+steps.map((label,i)=>
    '<button type="button" class="'+(i===stepIndex?'active':'')+'" data-visual-step="'+i+'" aria-current="'+(i===stepIndex?'step':'false')+'"><span>'+String(i).padStart(2,'0')+'</span>'+escapeCardText(label)+'</button>').join('')+'</nav>';
  const mainOpenerNames=(visual.hand||[]).concat(Object.values(visual.fieldBefore||{})).flatMap(item=>item&&item.card?Array.from({length:Math.max(1,Number(item.qty)||1)},()=>item.card):[]);
  const openingUnknown=(visual.hand||[]).concat(Object.values(visual.fieldBefore||{})).filter(item=>item&&!item.card).reduce((sum,item)=>sum+Math.max(1,Number(item.qty)||1),0);
  const startingState={hand:visual.hand||[],grave:[],banished:[],mainUnknownRemoved:openingUnknown};
  const startingBoard=comboBoardZones(Object.assign({},visual.fieldBefore||{},{grave:[],banished:[]}),startingState,visual.deckLists,mainOpenerNames);
  let body;
  if (stepIndex === 0) {
    body = '<section class="combo-visual-panel"><h3>Step 0 · Starting hand &amp; fields</h3><p>'+escapeCardText(combo.condition)+'</p></section>'+
      '<section class="combo-visual-panel"><div class="combo-visual-panel-heading"><h3>Starting hand</h3></div><div class="combo-hand-cards">'+comboStartingHandMarkup(visual.hand)+'</div></section>'+
      comboFieldBoardMarkup(startingBoard,'Starting field','')+
      (visual.opponentBefore?comboFieldBoardMarkup(visual.opponentBefore,'Opponent starting field',''):'');
  } else {
    const i = stepIndex - 1;
    const step = visual.steps[i], flow = step.flow || {};
    const piles = visual.piles[i] || {}, zoneState = visual.zoneStates[i] || {};
    const stepState = {...zoneState,grave:piles.grave||[],banished:piles.banished||[],mainUnknownRemoved:openingUnknown+(Number(zoneState.mainUnknownRemoved)||0)};
    const stepBoard = comboBoardZones(step.fieldAfter||{},stepState,visual.deckLists,mainOpenerNames);
    const inputs = flow.inputs || [], outputs = flow.outputs || [];
    const cards = entries => '<div class="combo-flow-cards">'+entries.map(card=>comboVisualCardMarkup(card,'combo-flow-card')).join('')+'</div>';
    const hasArrow = inputs.length && outputs.length && !flow.showSourceOnly;
    const chain=(step.chain||[]).length?'<div class="combo-chain"><h4>Effects in this Chain</h4><ol>'+(step.chain||[]).map(effect=>'<li><div>'+comboVisualCardMarkup({card:effect.card},'combo-chain-card')+'</div><p><strong>'+escapeCardText(effect.label)+'</strong><br>'+escapeCardText(effect.description)+'</p></li>').join('')+'</ol><small>Resolve in reverse order: Chain Link '+step.chain.length+' → 1.</small></div>':'';
    const diagram = hasArrow
      ? '<div class="combo-card-flow"><div><b class="combo-flow-heading">Cards involved</b>'+cards(inputs)+'</div><div class="combo-flow-arrow"><span>'+escapeCardText(flow.action||'')+'</span><b aria-hidden="true">→</b></div><div><b class="combo-flow-heading">Result</b>'+cards(outputs)+'</div></div>'
      : '<div class="combo-scale-activation">'+cards(inputs.length?inputs:outputs)+'<strong>'+escapeCardText(flow.action||'')+'</strong></div>';
    body = '<section class="combo-visual-panel combo-step-visual-panel"><div class="combo-visual-panel-heading"><h3>Step '+stepIndex+' of '+combo.steps.length+'</h3><p>'+escapeCardText(combo.steps[i])+'</p></div>'+chain+diagram+'</section>'+
      comboFieldBoardMarkup(stepBoard,'Step '+stepIndex,'',zoneState.hand||[])+
      (step.opponentAfter?comboFieldBoardMarkup(step.opponentAfter,'Opponent field after step '+stepIndex,''):'');
  }
  return '<div class="combo-visual-desktop">'+nav+body+comboResultAndControls(combo,stepIndex)+'</div>'+comboTextOnlyMarkup(combo,stepIndex,visual);
}
